/**
 *
 * OrganizationChart visualizes hierarchical organization data.
 *
 * [Live Demo](https://primevue.dev/organizationchart)
 *
 * @module organizationchartstyle
 *
 */
import type { BaseStyle, BaseStyleModule } from '@primevue/core/base/style';

export enum OrganizationChartClasses {
    /**
     * Class name of the root element
     */
    root = 'p-organizationchart',
    /**
     * Class name of the subtree (`ul`) element. The top-level subtree also carries `p-organizationchart-subtree-root`.
     */
    subtree = 'p-organizationchart-subtree',
    /**
     * Class name of the tree item (`li`) element
     */
    tree = 'p-organizationchart-tree',
    /**
     * Class name of the node element
     */
    node = 'p-organizationchart-node',
    /**
     * Class name of the node content element
     */
    content = 'p-organizationchart-node-content',
    /**
     * Class name of the node label element
     */
    label = 'p-organizationchart-node-label',
    /**
     * Class name of the node toggle button element
     */
    toggle = 'p-organizationchart-node-toggle-button',
    /**
     * Class name of the node toggle indicator element
     */
    toggleIndicator = 'p-organizationchart-node-toggle-button-icon'
}

export interface OrganizationChartStyle extends BaseStyle {}

declare const OrganizationChartStyle: BaseStyleModule;

export default OrganizationChartStyle;
